// PLAIN JAVASCRIPT - the bug is only discovered when this code actually runs
function calculateTotal(price, quantity) {
  return price * quantity;
}

const total = calculateTotal('29.99', 3);
// No error here. Later: '29.99' * 3 actually works due to JS coercion,
// but calculateTotal('29.99 dollars', 3) would silently produce NaN,
// discovered only when a user sees a broken total on screen.

// TYPESCRIPT - the bug is caught before the code ever runs
function calculateTotal(price: number, quantity: number): number {
  return price * quantity;
}

const total = calculateTotal('29.99', 3);
// COMPILE ERROR: Argument of type 'string' is not assignable to
// parameter of type 'number'.
// This is flagged immediately, directly in the editor, before the
// function is ever actually called with real data.

codingChallenge.starterCode:
