function calculateDiscount(price, percentOff) {
  return price - (price * percentOff);
}

const result1 = calculateDiscount(100, 0.2);
const result2 = calculateDiscount('100', 0.2);

// TODO: add type annotations to calculateDiscount's parameters and return type
// TODO: identify which call above would now produce a compile error, as a comment

codingChallenge.solutionExample:
function calculateDiscount(price: number, percentOff: number): number {
  return price - (price * percentOff);
}

const result1 = calculateDiscount(100, 0.2); // valid
const result2 = calculateDiscount('100', 0.2);
// COMPILE ERROR: Argument of type 'string' is not assignable to
// parameter of type 'number'. This call would be caught at compile
// time, before ever running, since '100' is a string, not a number.

sections.content:
Primitive types: string, number, boolean, null, undefined

Arrays: string[] (an array of strings), number[] (an array of numbers)

Object types and interfaces:
interface User {
  id: number;
  name: string;
  email: string;
  bio?: string;        // the ? makes this property optional
}

const user: User = { id: 1, name: 'Maya', email: 'maya@example.com' };
// bio is optional, so omitting it is valid

Union types (a value that can be one of several specific types):
function formatId(id: string | number): string {
  return `ID-${id}`;
}

Literal types (a value restricted to specific, exact values, often combined with unions):
type Status = 'pending' | 'active' | 'completed';
function updateStatus(status: Status) { /* ... */ }
updateStatus('archived'); // COMPILE ERROR - not one of the allowed values

sections.code:
interface Task {
  id: number;
  title: string;
  completed: boolean;
  dueDate?: string; // optional - not every task has a due date
}

function createTask(title: string): Task {
  return {
    id: Date.now(),
    title,
    completed: false
  };
  // valid - dueDate is optional, so omitting it is fine
}

function completeTask(task: Task): Task {
  return { ...task, completed: true };
}

function printTaskSummary(task: Task): string {
  const status: 'pending' | 'completed' = task.completed ? 'completed' : 'pending';
  return `${task.title} - ${status}${task.dueDate ? ` (due ${task.dueDate})` : ''}`;
}

const newTask = createTask('Write TypeScript lesson');
console.log(printTaskSummary(newTask)); // 'Write TypeScript lesson - pending'

// COMPILE ERROR if attempted:
// completeTask({ id: 1, title: 'Test' }); // missing required 'completed' property

