interface ApiResponse<T> {
  success: boolean;
  data: T;
}

interface ApiError {
  success: false;
  error: string;
}

// A generic function that wraps ANY data in the consistent response shape
function createSuccessResponse<T>(data: T): ApiResponse<T> {
  return { success: true, data };
}

// Used with genuinely different types, all type-safe, all reusing
// the exact same function
const userResponse = createSuccessResponse<User>({
  id: 1, name: 'Maya', email: 'maya@example.com'
});

const taskListResponse = createSuccessResponse<Task[]>([
  { id: 1, title: 'Write lesson', completed: false }
]);

function handleResponse<T>(response: ApiResponse<T>): T {
  if (!response.success) {
    throw new Error('Request failed');
  }
  return response.data; // TypeScript knows this is genuinely type T, not 'any'
}

const user = handleResponse(userResponse); // user is correctly typed as User
console.log(user.email); // TypeScript knows .email exists - autocomplete works correctly

