  success: boolean;
  data: T;
}

function wrapResult<T>(data: T): ApiResult<T> {
  return { success: true, data };
}

function unwrapResult<T>(result: ApiResult<T>): T {
  return result.data;
}

const numberResult = wrapResult(42);
const stringResult = wrapResult('hello');

const extractedNumber = unwrapResult(numberResult); // correctly typed as number
const extractedString = unwrapResult(stringResult); // correctly typed as string

