import { Request, Response, NextFunction } from 'express';

interface Task {
  id: number;
  title: string;
  completed: boolean;
}

interface CreateTaskBody {
  title: string;
}

function isValidTitle(value: unknown): value is string {
  return typeof value === 'string' && value.trim() !== '';
}

app.post(
  '/tasks',
  (req: Request<{}, {}, CreateTaskBody>, res: Response, next: NextFunction) => {
    try {
      // TypeScript assumes req.body.title is a string based on our type,
      // but we STILL runtime-validate, since a real request might not
      // actually match what we declared
      if (!isValidTitle(req.body.title)) {
        return res.status(400).json({ success: false, error: 'A non-empty title is required' });
      }

      const newTask: Task = {
        id: Date.now(),
        title: req.body.title.trim(),
        completed: false
      };

      res.status(201).json({ success: true, data: newTask });
    } catch (err) {
      next(err);
    }
  }
);

