codingChallenge.solutionExample:
import { Request, Response, NextFunction } from 'express';

interface ProductBody {
  name: string;
  price: number;
}

function isValidPrice(value: unknown): value is number {
  return typeof value === 'number' && value > 0;
}

function isValidName(value: unknown): value is string {
  return typeof value === 'string' && value.trim() !== '';
}

app.post(
  '/products',
  (req: Request<{}, {}, ProductBody>, res: Response, next: NextFunction) => {
    try {
      if (!isValidName(req.body.name) || !isValidPrice(req.body.price)) {
        return res.status(400).json({ success: false, error: 'A valid name and positive price are required' });
      }

      const newProduct = { id: Date.now(), name: req.body.name, price: req.body.price };
      res.status(201).json({ success: true, data: newProduct });
    } catch (err) {
      next(err);
    }
  }
);

