A shared interface, defined once in a location both frontend and backend code can import from (commonly a shared package, or a types folder referenced by both, depending on project structure — Module 10, lesson 9):

// shared/types.ts
export interface Task {
  id: number;
  title: string;
  completed: boolean;
}

export interface ApiResponse<T> {
  success: boolean;
  data: T;
}

Backend, importing and using the exact same interface:

import { Task, ApiResponse } from '../shared/types';

app.get('/tasks', (req: Request, res: Response<ApiResponse<Task[]>>) => {
  const tasks: Task[] = getTasksFromDatabase();
  res.json({ success: true, data: tasks });
});

Frontend, importing the SAME interface, directly extending Module 10, lesson 2's API client:

import { Task, ApiResponse } from '../shared/types';

async function fetchTasks(): Promise<Task[]> {
  const response = await fetch('/api/tasks');
  const result: ApiResponse<Task[]> = await response.json();
  return result.data; // correctly typed as Task[], not 'any'
}

