// shared/types.ts
export interface Task {
  id: number;
  title: string;
  completed: boolean;
}
export interface ApiResponse<T> {
  success: boolean;
  data: T;
}

// backend/routes/tasks.ts (lesson 5's typed Express, lesson 3's generics)
import { Task, ApiResponse } from '../../shared/types';

app.get('/api/tasks', (req: Request, res: Response<ApiResponse<Task[]>>) => {
  const tasks: Task[] = [{ id: 1, title: 'Write lesson', completed: false }];
  res.json({ success: true, data: tasks });
});

// frontend/api.ts (lesson 3's generics, Module 10 lesson 2's API client)
import { Task, ApiResponse } from '../../shared/types';

async function fetchTasks(): Promise<Task[]> {
  const response = await fetch('/api/tasks');
  if (!response.ok) throw new Error('Failed to fetch tasks');
  const result: ApiResponse<Task[]> = await response.json();
  return result.data;
}

// frontend/TaskList.tsx (lesson 4's typed React component)
function TaskList() {
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => {
    fetchTasks().then(setTasks).catch(console.error);
  }, []);

  return (
    <ul>
      {tasks.map((task: Task) => (
        <li key={task.id}>{task.title}</li>
      ))}
    </ul>
  );
}

