codingChallenge.solutionExample:
// shared/types.ts
export interface Comment {
  id: number;
  text: string;
  authorName: string;
}
export interface ApiResponse<T> {
  success: boolean;
  data: T;
}

// backend route
import { Comment, ApiResponse } from '../../shared/types';
app.get('/api/comments', (req: Request, res: Response<ApiResponse<Comment[]>>) => {
  const comments: Comment[] = [{ id: 1, text: 'Great post!', authorName: 'Sam' }];
  res.json({ success: true, data: comments });
});

// frontend component
import { Comment, ApiResponse } from '../../shared/types';

function CommentList() {
  const [comments, setComments] = useState<Comment[]>([]);

  useEffect(() => {
    fetch('/api/comments')
      .then((res) => res.json())
      .then((result: ApiResponse<Comment[]>) => setComments(result.data));
  }, []);

  return (
    <ul>
      {comments.map((comment: Comment) => (
        <li key={comment.id}>{comment.authorName}: {comment.text}</li>
      ))}
    </ul>
  );
}

// This shared typing guarantees that, at compile time, the backend route
// and frontend component agree on Comment's exact shape, catching mismatches
// in OUR OWN code before deployment. It does NOT guarantee that the actual
// deployed backend genuinely returns data matching this shape at runtime,
// nor does it replace the need for runtime validation against malicious
// or malformed real requests.
